def find_path(graph, start, goal):
    """
    Given a directed graph represented as a dictionary where each key is a node and the value is a list of neighboring nodes,
    find a path from start to goal. Return a list of nodes from start to goal (inclusive) if a path exists, otherwise return None.
    """
    if start not in graph or goal not in graph:
        return None

    # Initialize the path list and the set to keep track of visited nodes
    path = []
    visited = set()

    def explore(node):
        if node in visited:
            return None
        visited.add(node)
        if node == goal:
            return [node]
        for neighbor in graph[node]:
            result = explore(neighbor)
            if result is not None:
                return [node] + result
        return None

    return explore(start)
