def find_path(graph, start, goal):
    """
    Perform a path search algorithm (e.g., Depth First Search, Breadth First Search)
    on a directed graph to find a path from start to goal.

    :param graph: Dict mapping each node to a list of neighbouring nodes.
    :param start: The starting node.
    :param goal: The goal node.
    :return: A list of nodes from start to goal (inclusive) if a path exists, otherwise None.
    """
    def dfs(visited, graph, node, goal, path):
        if node == goal:
            return path + [node]
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                result = dfs(visited, graph, neighbor, goal, path + [node])
                if result:
                    return result
        return None

    visited = set()
    return dfs(visited, graph, start, goal, [start])
